import{_ as l,b as a,c as e,g as t}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach-homework/4.md","filePath":"articles/ai/books/ai-modern-approach-homework/4.md"}'),n={name:"articles/ai/books/ai-modern-approach-homework/4.md"};function o(d,i,r,_,s,p){return a(),e("div",null,[...i[0]||(i[0]=[t('<h2 id="简述爬山法-hill-climbing-和模拟退火-simulated-annealing-在跳出局部最优上的机制差异-并说明为什么模拟退火更有可能找到全局最优。" tabindex="-1">简述爬山法（Hill Climbing）和模拟退火（Simulated Annealing）在跳出局部最优上的机制差异，并说明为什么模拟退火更有可能找到全局最优。</h2><ul><li>爬山算法会出现山岭，山岭意味着进入循环状态，跳出的策略：随机漫步</li><li>模拟退火算法增加了随时间变化的启发函数</li></ul><h2 id="某遗传算法使用二进制编码-种群大小50-交叉率0-8-变异率0-01。请解释" tabindex="-1">某遗传算法使用二进制编码，种群大小50，交叉率0.8，变异率0.01。请解释：</h2><ul><li>交叉和变异分别起到什么作用？</li><li>如果变异率设为0，算法会有什么风险？</li></ul><h2 id="考虑函数-f-x-x-2-4sin⁡-3x-在区间-4-4-上的最小值问题。" tabindex="-1">考虑函数 f(x)=x^2+4sin⁡(3x) 在区间 [-4,4] 上的最小值问题。</h2><ul><li>(a) 若使用梯度下降（步长固定为0.1），从 x=2 出发，手工迭代两步（计算导数值）。</li><li>(b) 解释为什么梯度下降可能陷入局部最优，而模拟退火可以缓解此问题。</li></ul><h2 id="你有一个10个城市的旅行商问题-tsp-距离矩阵已知。请设计一个简单爬山法的邻域操作-例如交换两个城市的位置-并说明如何评价一个解。如果使用模拟退火-需要额外设置什么参数-简述这些参数如何影响搜索。" tabindex="-1">你有一个10个城市的旅行商问题（TSP），距离矩阵已知。请设计一个简单爬山法的邻域操作（例如交换两个城市的位置），并说明如何评价一个解。如果使用模拟退火，需要额外设置什么参数？简述这些参数如何影响搜索。</h2><h2 id="pid控制器参数优化" tabindex="-1">PID控制器参数优化：</h2><p>一个PID控制器有三个参数 K_p,K_i,K_d，需调整使得某个系统的响应（如超调量、稳态误差、调节时间）的综合性能指标 J(K_p,K_i,K_d) 最小。性能指标通过仿真获得，没有解析导数。</p><ul><li>(a) 为什么不能用梯度下降法直接优化？</li><li>(b) 请设计一个模拟退火或遗传算法的方案（包括解表示、评价函数、邻域/交叉变异、终止条件），并说明如何选择初始温度和降温策略。</li><li>(c) 讨论若使用遗传算法，种群大小、交叉率、变异率对优化结果的影响。</li></ul><h2 id="非确定性环境规划" tabindex="-1">非确定性环境规划：</h2><ul><li>假设你有一个自动送货机器人，在走廊中移动，但轮子可能打滑（移动一步有0.8概率成功到邻格，0.2概率原地不动）。机器人可感知当前格子是否为目标（完全可观测当前位置）。请画出从起点S到目标G的与或图的局部结构（假设走廊直线型，3个格子：左、中、右），并写出一个条件规划（用if-then形式）保证总能到达G。讨论为什么普通序列规划在此环境中会失败。</li></ul>',12)])])}const m=l(n,[["render",o]]);export{c as __pageData,m as default};
